async () => {
const txt = (s) => (s || '').replace(/\s+/g, ' ').trim();
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
const swatchButtons = (scope) => [...scope.querySelectorAll('button[class*=selectButton]')];
const shown = (scope) => swatchButtons(scope).map((b) => txt(b.getAttribute('aria-label')));
const groups = (scope) => [...scope.querySelectorAll('[class*=groupTitle]')].map((e) => txt(e.innerText));
const filterButton = (scope, re) => [...scope.querySelectorAll('button[aria-haspopup=listbox]')].find((b) => re.test(txt(b.innerText)));
const MATERIAL = /^(Material|Show all|HPL|Porcelain|Fenix|Solid Surface|Technolite|Technomat|Glass|Glass GL|Glass MT|Laminate)$/;
const PRICE = /^(Price|Standard \$|Classic \$\$|Specialty \$\$\$|Exclusive \$\$\$\$)$/;
const close = async () => { document.body.dispatchEvent(new MouseEvent('mousedown', { bubbles: true })); await wait(300); };
const openMenu = async (scope, re, name) => { const b = scope.querySelectorAll('button[aria-haspopup=listbox]')[0] && filterButton(scope, re); if (!b) return null; b.click(); await wait(500); return [...document.querySelectorAll(`[role=listbox][aria-label=${name}]`)].pop(); };
const labels = (lb) => [...lb.querySelectorAll('[role=option]')].map((o) => txt(o.querySelector('span')?.innerText || o.innerText));
const pickIn = async (scope, re, name, text, expand) => {
  const lb = await openMenu(scope, re, name);
  if (!lb) return { err: 'NO ' + name + ' MENU' };
  if (expand) { const caret = lb.querySelector(`button[aria-label="Expand ${expand}"]`); if (!caret) { const offered = labels(lb); await close(); return { err: 'NO CARET ' + expand, offered }; } caret.click(); await wait(300); }
  const btn = [...lb.querySelectorAll('button')].find((b) => txt(b.querySelector('span')?.innerText || b.innerText) === text);
  if (!btn) { const offered = labels(lb); await close(); return { err: 'NO ITEM ' + text, offered }; }
  btn.click(); await wait(900);
  const names = shown(scope);
  return { pick: text, count: names.length, swatches: names.length <= 4 ? names : undefined, groups: groups(scope) };
};
const pick = (scope, text, expand) => pickIn(scope, MATERIAL, 'Material', text, expand);
const solidSurfaceSwatches = (scope) => swatchButtons(scope)
  .filter((b) => /^Matte White/.test(txt(b.getAttribute('aria-label'))))
  .map((b) => ({ name: txt(b.getAttribute('aria-label')), group: txt(b.closest('section')?.querySelector('[class*=groupTitle]')?.innerText), unavailable: b.getAttribute('aria-disabled') === 'true', chosen: b.getAttribute('aria-pressed') === 'true' }));
const panelOf = async (title) => {
  const trig = [...document.querySelectorAll('button')].find((b) => txt(b.innerText) === title && b.hasAttribute('aria-expanded'));
  if (!trig) return null;
  if (trig.getAttribute('aria-expanded') !== 'true') { trig.scrollIntoView({ block: 'center' }); trig.click(); await wait(800); }
  return document.getElementById(trig.getAttribute('aria-controls') || '');
};

const panel = await panelOf('Countertop Color');
if (!panel) return { err: 'NO COUNTERTOP COLOR PANEL' };
const r = { noFilter: { count: shown(panel).length, groups: groups(panel) } };
let lb = await openMenu(panel, MATERIAL, 'Material');
r.menu = labels(lb);
const caret = lb.querySelector('button[aria-label="Expand Solid Surface"]');
r.solidSurfaceIsHeader = !!caret;
if (caret) { caret.click(); await wait(300); r.menuExpanded = labels(lb); }
await close();
r.technolite = await pick(panel, 'Technolite', 'Solid Surface');
r.technomat = await pick(panel, 'Technomat', 'Solid Surface');
r.header = await pick(panel, 'Solid Surface');
r.solidSurfaceSwatches = solidSurfaceSwatches(panel);
lb = await openMenu(panel, PRICE, 'Price');
r.priceOfferedForSolidSurface = lb ? labels(lb) : 'NO PRICE MENU';
await close();
r.priceTiers = {};
for (const tier of (Array.isArray(r.priceOfferedForSolidSurface) ? r.priceOfferedForSolidSurface : []).filter((t) => t !== 'Show all')) {
  const res = await pickIn(panel, PRICE, 'Price', tier);
  r.priceTiers[tier] = res.swatches ?? res;
}
await pickIn(panel, PRICE, 'Price', 'Show all');
r.glass = await pick(panel, 'Glass');
r.showAll = await pick(panel, 'Show all');
return r;
}

